"""
Autonomous agents API router.

A profile becomes an **agent** when its ``autonomy`` block is enabled: it gets a
board, a cadence and a mandate, and the background worker takes its shifts (see
:mod:`codx.junior.autonomy`). This router is the control surface of that feature
for the UI and for scripts.

This router follows the project convention: it lives in ``codx/junior/api/`` and
exports a ``router`` attribute, so it is discovered automatically by
:func:`codx.junior.api.discover_routers` and mounted under ``/api`` — **no change
is needed in ``app.py``**. The project comes from the request session (the
``codx_path`` query parameter / ``x-codx-path`` header handled by the session
middleware).

Resources
---------
GET    /api/autonomy/status                       agents, cadence, cost, next wake
GET    /api/autonomy/agents                       same payload, agents only
PUT    /api/autonomy/agents/{profile_name}        configure (enable/disable/cadence/mandate)
POST   /api/autonomy/agents/{profile_name}/wake   ask for a shift now (or at ``when``)
POST   /api/autonomy/agents/{profile_name}/schedule   set the next shift instant
POST   /api/autonomy/agents/{profile_name}/run    run one shift synchronously (debug)

Conventions
-----------
* ``PUT`` is an **upsert** on the autonomy block: only the provided fields change,
  the rest of the profile (content, tools, knowledge, linked profiles) is never
  touched, because the write goes through ``ProfileManager.save_profile``.
* ``POST .../wake`` never runs an AI turn inline: it records the intent and the
  background worker executes it, so an API request always stays short.
* ``POST .../run`` is the only blocking endpoint and is meant for debugging.

Made with ❤️ by codx-junior
"""

from __future__ import annotations

import logging
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, HTTPException, Query, Request
from pydantic import BaseModel, Field

from . import get_current_session

logger = logging.getLogger(__name__)

router = APIRouter(prefix="/autonomy", tags=["autonomy"])


class AutonomyConfigRequest(BaseModel):
    """Partial update of the autonomy block of a profile."""

    enabled: Optional[bool] = Field(
        default=None, description="Turn autonomy on/off for this profile."
    )
    board: Optional[str] = Field(
        default=None, description="Board of the agent (created when missing)."
    )
    interval_minutes: Optional[int] = Field(
        default=None, description="Cadence between two automatic shifts."
    )
    mode: Optional[str] = Field(
        default=None, description="'active' (acts) or 'dry_run' (reports only)."
    )
    budget_cxjcoins: Optional[float] = Field(
        default=None, description="Budget hint for one shift (0 = project default)."
    )
    max_runtime_minutes: Optional[int] = Field(
        default=None, description="Hard limit of one shift, in minutes."
    )
    max_agenda: Optional[int] = Field(
        default=None, description="How many due tasks one shift must handle."
    )
    instructions: Optional[str] = Field(
        default=None, description="Standing orders added to the profile mandate."
    )


class WakeRequest(BaseModel):
    """Optional schedule for a manually requested shift."""

    when: Optional[str] = Field(
        default=None,
        description=(
            "Schedule expression: '+2d', '3 hours', an ISO date "
            "(2026-04-01) or an ISO instant. Empty means 'as soon as possible'."
        ),
    )


def _service(request: Request) -> Any:
    """Build the :class:`AutonomyService` of the request project."""
    from codx.junior.autonomy.service import AutonomyService

    session = get_current_session(request)
    settings = getattr(session, "settings", None)
    if settings is None:
        raise HTTPException(
            status_code=400,
            detail="No project in the request: pass the codx_path of a project.",
        )
    return AutonomyService(settings=settings)


def _save_autonomy(service: Any, profile_name: str, payload: AutonomyConfigRequest):
    """Merge the payload into the profile autonomy block and persist it."""
    from codx.junior.autonomy.models import AutonomyConfig

    manager = service._profiles()
    profile = manager.read_profile(profile_name)
    if profile is None:
        raise HTTPException(
            status_code=404, detail=f"profile '{profile_name}' does not exist"
        )
    data = dict(getattr(profile, "autonomy", None) or {})
    for key, value in payload.model_dump(exclude_none=True).items():
        data[key] = value
    profile.autonomy = AutonomyConfig(**data).normalized().model_dump()
    manager.save_profile(profile=profile)
    return profile


@router.get("/status", summary="Autonomous agents of the project")
def get_autonomy_status(request: Request) -> Dict[str, Any]:
    """Return every agent with its configuration, runtime state and next wake."""
    return _service(request).status()


@router.get("/agents", summary="Autonomous agents only")
def get_autonomy_agents(request: Request) -> List[Dict[str, Any]]:
    """Return the ``agents`` list of :func:`get_autonomy_status`."""
    return _service(request).status().get("agents") or []


@router.put("/agents/{profile_name}", summary="Configure the autonomy of a profile")
def put_autonomy(
    request: Request,
    profile_name: str,
    payload: AutonomyConfigRequest,
) -> Dict[str, Any]:
    """
    Update the autonomy block of *profile_name*.

    Only the provided fields change; the profile instructions, tools, knowledge
    and linked profiles are preserved.
    """
    service = _service(request)
    _save_autonomy(service, profile_name, payload)
    for entry in service.status().get("agents") or []:
        if str(entry.get("agent", "")).lower() == profile_name.lower():
            return entry
    return {"agent": profile_name, "enabled": False, "note": "autonomy is disabled"}


@router.post("/agents/{profile_name}/enable", summary="Enable autonomy")
def post_autonomy_enable(request: Request, profile_name: str) -> Dict[str, Any]:
    """Switch the profile into an autonomous agent."""
    service = _service(request)
    _save_autonomy(service, profile_name, AutonomyConfigRequest(enabled=True))
    return service.status()


@router.post("/agents/{profile_name}/disable", summary="Disable autonomy")
def post_autonomy_disable(request: Request, profile_name: str) -> Dict[str, Any]:
    """Stop the profile from taking shifts (its board and history are kept)."""
    service = _service(request)
    _save_autonomy(service, profile_name, AutonomyConfigRequest(enabled=False))
    return service.status()


@router.post("/agents/{profile_name}/wake", summary="Request a shift")
def post_autonomy_wake(
    request: Request,
    profile_name: str,
    payload: Optional[WakeRequest] = None,
) -> Dict[str, Any]:
    """
    Record "take a shift now" (or at ``when``).

    The background worker executes it; nothing runs inline.
    """
    service = _service(request)
    try:
        return service.request_wake(profile_name, when=(payload.when if payload else "") or "")
    except ValueError as ex:
        raise HTTPException(status_code=400, detail=str(ex))


@router.post("/agents/{profile_name}/schedule", summary="Set the next shift")
def post_autonomy_schedule(
    request: Request,
    profile_name: str,
    when: str = Query(description="Schedule expression, e.g. '+2d' or '2026-04-01'"),
) -> Dict[str, Any]:
    """Set the instant of the next automatic shift of the agent."""
    service = _service(request)
    try:
        return service.schedule_wake(profile_name, when)
    except ValueError as ex:
        raise HTTPException(status_code=400, detail=str(ex))


@router.post("/agents/{profile_name}/run", summary="Run one shift now (blocking)")
async def post_autonomy_run(request: Request, profile_name: str) -> Dict[str, Any]:
    """
    Take one shift immediately and return its report.

    Debugging endpoint: a real shift can last minutes, so the UI uses
    ``/wake`` and reads ``/status`` instead.
    """
    service = _service(request)
    try:
        return await service.run_shift(profile_name, force=True, trigger="api")
    except ValueError as ex:
        raise HTTPException(status_code=400, detail=str(ex))

